mapper.select:
SELECT * FROM
audio_tasks

    AND user_id = #{dto.userId}
    AND status = #{dto.status}

ORDER BY create_time DESC

mapper.delete:
DELETE FROM audio_tasks
WHERE id = #{id}
AND user_id = #{userId}

mapper.update:
UPDATE audio_tasks SET status = #{newStatus}
    , result_url = #{resultUrl}
    , audio_size = #{audioSize}
    , error_msg = #{errorMsg}
    , completed_date = #{completedDate}
    WHERE id = #{id}
      AND status = #{expectedStatus}
      AND retry_time = #{attempt}

UPDATE audio_tasks
SET status = #{retriedStatus},
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = #{failedStatus}
